steps.script:
for uid in ["U_CUSTODIAN_GUARD_B", "U_WITCHSEEKERS_D"]:
	var f = GameState.state.units[uid].get("flags", {})
	for k in ["moved", "advanced", "fell_back", "remained_stationary", "has_shot", "cannot_charge", "move_cap_inches"]:
		f.erase(k)
var ws = GameState.state.units["U_WITCHSEEKERS_D"]
var i = 0
for m in ws.models:
	m["position"] = {"x": 300.0 + i * 45.0, "y": 1330.0}
	i += 1
# OBJ-GAP-2: the fixture's Guard sits with base edges ~3.4" from obj_nml_1 —
# IN range by the real rule (the old AI read model centres, 4.2"). Step it
# 1" back so it is genuinely off the objective and must be planned onto it.
for m in GameState.state.units["U_CUSTODIAN_GUARD_B"].models:
	m["position"] = {"x": float(m.position.x), "y": float(m.position.y) + 40.0}
var nml = {}
for o in GameState.state.board.objectives:
	if o.id == "obj_nml_1":
		nml = o
for m in GameState.state.units["U_CUSTODIAN_GUARD_B"].models:
	if m.get("alive", true) and MissionManager.model_in_objective_range(m, nml):
		return false
return true
